<?php
namespace App\Filament\Admin\Resources\InsuranceProducts\Pages;
use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Filament\Admin\Resources\InsuranceProducts\InsuranceProductResource;use App\Models\{CoverageDefinition,InsuranceProduct};use Filament\Resources\Pages\CreateRecord;
final class CreateInsuranceProduct extends CreateRecord{protected static string $resource=InsuranceProductResource::class;protected function mutateFormDataBeforeCreate(array$data):array{$data['version']=(InsuranceProduct::where(['carrier_id'=>$data['carrier_id'],'code'=>$data['code']])->max('version')??0)+1;$data['status']='DRAFT';$data['created_by']=auth()->id();$data['coverages']=[];$data['eligibility_rules']=$data['eligibility_rules']??[];return$data;}protected function afterCreate():void{$ids=CoverageDefinition::where(['insurance_line_id'=>\App\Models\InsuranceLine::where('code',$this->record->line_code)->value('id'),'mandatory'=>true,'status'=>'ACTIVE'])->pluck('id');$this->record->coverageDefinitions()->sync($ids->mapWithKeys(fn($id,$i)=>[$id=>['display_order'=>$i,'configuration'=>'{}']])->all());app(AuditWriter::class)->record('catalogue.product.created','insurance_product',$this->record->id,['version'=>$this->record->version]);app(OutboxWriter::class)->record('catalogue.product.created','insurance_product',$this->record->id,['product_id'=>$this->record->id,'version'=>$this->record->version]);}}
